return {["sort"]=0,["roomList"]={{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[醉梦三生馆]],["permission"]=1,["rightDown"]=[[fb608_08]],["enterable"]=1,["up"]=[[fb608_04]],["dsc"]=[[馆内两侧酒架藏有各地佳酿，更独有醉三生。此酒入口甘醇，回味绵长，后劲极大，可使人醉数日不醒。馆内中央曲水流觞，设蒲团、桌椅、武器架，弟子常在此饮酒对剑。]],["fullName"]=[[醉梦三生馆(fb608_05)]],["visible"]=1,["leftDown"]=[[fb608_07]],["dirIndex"]=0,["unit3"]=[[npc03]],["unit2"]=[[npc06b]],["unit1"]=[[npc06c]],["canLeave"]=1,["id"]=[[fb608_05]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[紫藤苑]],["permission"]=1,["enterable"]=1,["up"]=[[fb608_02]],["dsc"]=[[种满了紫藤萝，花开如瀑，从花架倾泻而下，令人目眩神迷。置身其中，满眼花瀑，飘然若仙。]],["down"]=[[fb608_05]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[紫藤苑(fb608_04)]],["canLeave"]=1,["id"]=[[fb608_04]],["mapHide"]=0},{["operations"]={},["rightUp"]=[[fb608_05]],["connectPoint"]=0,["name"]=[[曲廊]],["permission"]=1,["left"]=[[fb608_06]],["rightDown"]=[[fb608_11]],["enterable"]=1,["stepMusic"]=[[jiaobu]],["dsc"]=[[回环曲折的走廊]],["fullName"]=[[曲廊(fb608_07)]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc10d]],["unit2"]=[[npc09d]],["unit1"]=[[npc07d]],["canLeave"]=1,["id"]=[[fb608_07]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb608_07]],["connectPoint"]=0,["name"]=[[风月坊]],["permission"]=1,["fullName"]=[[风月坊(fb608_06)]],["enterable"]=1,["dsc"]=[[此坊名风月，却非俗世所说之地。坊内门庭四开，外临小池，垂柳摇曳，凡风吹动，坊内轻纱飘扬。若是月夜明澈之际，隔纱望月，听风舞剑十分自在。如此得人间风月，不羡俗世。]],["down"]=[[fb608_12]],["visible"]=1,["dirIndex"]=0,["unit3"]=[[npc10i]],["unit2"]=[[npc09i]],["unit1"]=[[npc07i]],["canLeave"]=1,["id"]=[[fb608_06]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb608_02]],["connectPoint"]=0,["name"]=[[西厢房]],["permission"]=1,["enterable"]=1,["dsc"]=[[供客人居住之所，环境清幽，陈设雅致。房前有一口井，井水清甜甘冽，泡茶极佳。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[西厢房(fb608_01)]],["canLeave"]=1,["id"]=[[fb608_01]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[东厢房]],["permission"]=1,[